                'actual' => null,
                'event' => 3,
            ],
        ]];
        yield 'persist__ticket_persist_first' => ['ticket', [
            'feature' => 'persist',
            'id' => 'ticket_persist_first',
            'name' => 'persist__ticket_persist_first',
            'scenario' => 'first',
            'expected' => 'open',
            'event' => 'submit',
            'stored' => 'open',
            'expect' => [
